#!/usr/bin/env python3
"""R1-2 benchmark for the E6 x U(1)_F Higgs vacuum.

The E6 singlet superpotential and the gauge-boson spectrum follow the
normalizations of Babu, Bajc and Susic, JHEP 05 (2015) 108.  The script
constructs a concrete F- and D-flat benchmark, writes the explicit 78 x 78
Gram mass matrix in an SM mass-eigenstate basis, and checks its kernel.

All dimensionful quantities are expressed in units of M_G.  The written
matrix is M_ab/(g_E6^2 M_G^2), in the convention L_mass = g_E6^2 A M A.
"""

from __future__ import annotations

import csv
import json
import math
from pathlib import Path

import numpy as np


ROOT = Path(__file__).resolve().parent
OUT = ROOT / "TD3R_IVE18_R1_outputs"

SQRT2 = math.sqrt(2.0)
SQRT56 = math.sqrt(5.0 / 6.0)


# Field order: 2 + 2 + 5 + 5 + 5 = 19 SM-singlet directions.
FIELD_NAMES = [
    "c1", "c2", "d1", "d2",
    "e1", "e2", "e3", "e4", "e5",
    "f1", "f2", "f3", "f4", "f5",
    "u1", "u2", "v", "w", "y",
]


def benchmark_parameters() -> dict[str, float]:
    """Exact radical parameter ratios for the unit-VEV benchmark."""
    lam8 = 1.0
    lam1 = -1.0 / (3.0 * SQRT2)
    m351 = 5.0 / (3.0 * SQRT2)
    lam3 = -3.0 / (2.0 * SQRT2) + SQRT56 / 2.0
    lam7 = (1.0 / SQRT2 - SQRT56) / (SQRT56 - 1.0 / (3.0 * SQRT2))
    m78 = SQRT56 * (lam7 + 1.0) / 4.0
    p = 1.0 / (6.0 * SQRT2) + SQRT56 / 2.0
    m27 = -2.0 * lam3 + p * lam7
    return {
        "m27": m27,
        "m351": m351,
        "m78": m78,
        "lambda1": lam1,
        "lambda2": lam1,
        "lambda3": lam3,
        "lambda4": lam3,
        "lambda5": 0.0,
        "lambda6": 0.0,
        "lambda7": lam7,
        "lambda8": lam8,
        "kappaF": 1.0,
        "vF": 1.0,
        "xiF": 0.0,
    }


def benchmark_vevs() -> np.ndarray:
    """Main-vacuum ansatz with every nonzero GUT VEV set to M_G."""
    values = {
        "c1": 0.0, "c2": 1.0, "d1": 0.0, "d2": 1.0,
        "e1": 1.0, "e2": 0.0, "e3": 1.0, "e4": 1.0, "e5": 0.0,
        "f1": 1.0, "f2": 0.0, "f3": 1.0, "f4": 1.0, "f5": 0.0,
        "u1": 0.0, "u2": 0.0, "v": 1.0, "w": 1.0, "y": 0.0,
    }
    return np.asarray([values[name] for name in FIELD_NAMES], dtype=float)


